ack.\"] = \"Applicata la preimpostazione %s per %sx%s. Riposizionati %d elementi attivi; gli elementi Predefiniti e Disattivati sono rimasti al loro posto. Salva prima un profilo per poter tornare facilmente indietro.\",\n [\"Applied the\"] = \"Applicato:\",\n [\"Apply recommended positions\"] = \"Applica posizioni consigliate\",\n [\"Apply selected\"] = \"Applica selezionato\",\n [\"Applying a read-only preset creates your editable copy.\"] = \"Applicare una preimpostazione di sola lettura crea una copia modificabile.\",\n [\"Area\"] = \"Area\",\n [\"Available\"] = \"Disponibile\",\n [\"Awaiting API support\"] = \"Awaiting API support\",\n [\"Azeroth Survivors compatibility\"] = \"Compatibilità con Azeroth Survivors\",\n [\"Baby Crying\"] = \"Pianto di neonato\",\n [\"Back\"] = \"Indietro\",\n [\"Bearings to known bosses, lairs and caches. Choose a rail or free markers.\"] = \"Direzioni di boss, covi e forzieri noti. Scegli una scala o indicatori liberi.\",\n [\"Below the player frame\"] = \"Sotto il riquadro del giocatore\",\n [\"Below the target frame\"] = \"Sotto il riquadro del bersaglio\",\n [\"Boss / guardian / lair kill sound\"] = \"Suono uccisione boss o guardiano\",\n [\"Boss damage only\"] = \"Solo danni ai boss\",\n [\"Boss, Guardian and elite health bars.\"] = \"Barre della salute di boss, Guardiani ed élite.\",\n [\"Bosses\"] = \"Boss\",\n [\"Bottom\"] = \"In basso\",\n [\"Buffs and debuffs\"] = \"Benefici e penalità\",\n [\"Buffs/Debuffs\"] = \"Benefici/Penalità\",\n [\"Buffs/Debuffs on the player frame\"] = \"Benefici/Penalità nel riquadro del giocatore\",\n [\"Build and stats beside card choices\"] = \"Build e statistiche ai bordi delle carte\",\n [\"Build rows\"] = \"Righe della configurazione\",\n [\"Button row (optional)\"] = \"Riga di pulsanti (facoltativa)\",\n [\"CSGO Okay Let’s Go\"] = \"CSGO Okay Let’s Go\",\n [\"Cache\"] = \"Forziere\",\n [\"Camera and marks\"] = \"Visuale e marcatori\",\n [\"Camera as far out as it goes (50)\"] = \"Allonta