er\"] = \"Come il giocatore\",\n [\"Same as the party (you join it)\"] = \"Come il gruppo (ne fai parte)\",\n [\"Same as the target (combined)\"] = \"Come il bersaglio (combinati)\",\n [\"Save a profile first if you want an easy way back.\"] = \"Salva prima un profilo per poter tornare facilmente indietro.\",\n [\"Save current as profile\"] = \"Salva attuale come profilo\",\n [\"Save named HUD profiles, apply one later, or copy a layout string to share it. Per-character layouts can be enabled in Settings.\"] = \"Salva profili HUD con nome, applicali in seguito o copia un codice per condividerli. Le disposizioni per personaggio si attivano nelle impostazioni.\",\n [\"Saved named profiles:\"] = \"Profili salvati con nome:\",\n [\"Saved profiles\"] = \"Profili salvati\",\n [\"Scale\"] = \"Scala\",\n [\"Setup\"] = \"Configurazione\",\n [\"Shield\"] = \"Scudo\",\n [\"Show Slim Suite above the level-up and new-item cards\"] = \"Mostra Slim Suite sopra le schermate dei livelli e dei nuovi oggetti\",\n [\"Show all six buttons at all times, even empty ones\"] = \"Mostra sempre tutti e sei i pulsanti, anche vuoti\",\n [\"Show and move Slim Suite's replacement.\"] = \"Mostra e sposta la versione di Slim Suite.\",\n [\"Show boss and Guardian kills\"] = \"Mostra le uccisioni di boss e Guardiani\",\n [\"Show boss and lair debuffs and remaining time on enemy nameplates (native or modern)\"] = \"Mostra penalità e durata di boss e tane sulle targhe nemiche (originali o moderne)\",\n [\"Show boss and lair debuffs and remaining time on modern enemy frames\"] = \"Mostra penalità e durate di boss e tane nei riquadri moderni\",\n [\"Show bosses\"] = \"Mostra boss\",\n [\"Show bosses on the minimap\"] = \"Mostra i boss sulla minimappa\",\n [\"Show build spells\"] = \"Mostra incantesimi\",\n [\"Show caches on the minimap\"] = \"Mostra i forzieri sulla minimappa\",\n [\"Show character faces\"] = \"Mostra i ritratti dei personaggi\",\n [\"Show chests\"] = \"Mostra forzieri\",\n [\"Show debuffs on the bars\"] = \"Mostra le penalità sulle barre\",\n [\"Show feature\"] = \"Mostra funzione\",\n [\"Show green absorb amounts on player and party frames (when the client exposes them)\"] = \"Mostra l'assorbimento verde nei riquadri del giocatore e del gruppo (se il client lo fornisce)\",\n [\"Show heals\"] = \"Mostra cure\",\n [\"Show lairs\"] = \"Mostra covi\",\n [\"Show lairs and their refill timer\"] = \"Mostra le tane e il tempo di rigenerazione\",\n [\"Show lairs on the minimap, with their 3:00 refill timer\"] = \"Mostra le tane sulla minimappa con il tempo di rigenerazione di 3:00\",\n [\"Show location and difficulty\"] = \"Mostra luogo e difficoltà\",\n [\"Show map name and difficulty\"] = \"Mostra nome della mappa e difficoltà\",\n [\"Show my layout\"] = \"Mostra la mia disposizione\",\n [\"Show native enemy nameplates\"] = \"Mostra le targhe originali dei nemici\",\n [\"Show the game's nearest Guardian lair flag on minimap\"] = \"Mostra sulla minimappa la bandiera della tana del Guardiano più vicino\",\n [\"Show the local clock\"] = \"Mostra l'orologio locale\",\n [\"Show the target's buffs and debuffs\"] = \"Mostra benefici e penalità del bersaglio\",\n [\"Show the zone and Heroic affixes under it\"] = \"Mostra zona e modificatori eroici sotto l'orologio\",\n [\"Show worn items\"] = \"Mostra oggetti equipaggiati\",\n [\"Side achievements\"] = \"Side achievements\",\n [\"Side achievements button\"] = \"Side achievements button\",\n [\"Size & layout\"] = \"Dimensioni e disposizione\",\n [\"Skip setup\"] = \"Salta configurazione\",\n [\"Slim Suite\"] = \"Slim Suite\",\n [\"Slim Suite error log\"] = \"Registro errori di Slim Suite\",\n [\"Slim Suite recommends the\"] = \"Slim Suite consiglia\",\n [\"Slim Suite replaces the game HUD automatically. Use Toggle UI Settings to arrange it, or Go back to vanilla to restore the original interface.\"] = \"Slim Suite sostituisce automaticamente l’interfaccia di gioco. Attiva le impostazioni dell’interfaccia per sis